/* KCMC_HOME_OPTION_B_20261013: one-card cover using the real KCMC building photo. */
.home-cover.hero.hero-imagery{
  position:relative;
  min-height:clamp(560px,48vw,760px);
  padding:0;
  display:grid;
  grid-template-columns:minmax(300px,.8fr) minmax(0,1.4fr);
  align-items:stretch;
  overflow:hidden;
  background:#0d2235;
  color:#0d2235;
  border-bottom:0;
  color-scheme:light;
}
.home-cover.hero-imagery:after{
  content:none;
}
.home-cover .home-cover-photo{
  position:relative;
  grid-column:2;
  grid-row:1;
  width:100%;
  height:100%;
  object-fit:contain;
  object-position:center;
  opacity:1;
  filter:none;
}
.home-cover-layout{
  position:relative;
  z-index:2;
  grid-column:1;
  grid-row:1;
  width:100%;
  display:flex;
  align-items:center;
  padding:24px;
}
.home-cover-card{
  width:100%;
  padding:clamp(20px,2vw,32px);
  border-radius:26px;
  background:rgba(250,247,239,.96);
  box-shadow:0 24px 60px rgba(7,18,28,.24);
  backdrop-filter:blur(2px);
}
.home-cover :where(a,button):focus-visible{outline:3px solid #17324c;outline-offset:4px}
.home-cover .eyebrow{
  color:#9a6a20;
}
.home-cover h1{
  color:#17324c;
  font-size:clamp(2.6rem,3.6vw,4rem);
  line-height:.98;
  margin:.25em 0 .28em;
}
.home-cover p.lead{
  color:#486172;
  max-width:36rem;
}
.home-cover-actions{
  display:grid;
  grid-template-columns:repeat(3,minmax(0,1fr));
  gap:12px;
  margin-top:24px;
}
.home-cover .home-cover-actions .action{
  min-height:96px;
  padding:12px;
  border:1px solid #cad4da;
  border-radius:18px;
  background:rgba(255,255,255,.92);
  color:#17324c;
  box-shadow:none;
}
.home-cover .home-cover-actions .action:first-child{
  background:#17324c;
  color:#fff;
  border-color:#17324c;
}
.home-cover .home-cover-actions .action span{
  color:#5c7180;
}
.home-cover .home-cover-actions .action:first-child span{
  color:#d7e2e8;
}
.home-worship-strip{
  background:#f7f3eb;
  color:#17324c;
  border-top:1px solid #e0d8c9;
  border-bottom:1px solid #e0d8c9;
}
.home-worship-strip-inner{
  display:grid;
  grid-template-columns:auto minmax(0,1fr) auto;
  gap:28px;
  align-items:center;
  padding-top:26px;
  padding-bottom:26px;
}
.home-worship-times{
  display:grid;
  gap:5px;
}
.home-worship-times .eyebrow{
  color:#526b7c;
}
.home-worship-times strong{
  font-size:clamp(2rem,4vw,3.4rem);
  line-height:1;
  white-space:nowrap;
}
.home-worship-copy{
  display:grid;
  gap:5px;
  padding-left:28px;
  border-left:1px solid #cfc6b7;
}
.home-worship-copy b{
  font-size:1.05rem;
}
.home-worship-copy span{
  color:#5c7180;
  line-height:1.55;
}
body:has([data-view="home"].active) .phase6-bulletin-fab{display:none}
.home-bulletin-link{
  white-space:nowrap;
  background:#fff;
  color:#17324c;
  border-color:#b9c5cc;
}
@media(max-width:1100px){
  .home-cover.hero.hero-imagery{
    min-height:auto;
    display:block;
    padding:0;
  }
  .home-cover .home-cover-photo{
    position:relative;
    width:100%;
    height:auto;
    aspect-ratio:1402/1122;
    object-fit:contain;
    object-position:center;
  }
  .home-cover.hero-imagery:after{
    display:none;
  }
  .home-cover-layout{
    margin-top:0;
    width:min(1120px,calc(100% - 30px));
    padding:18px 0 26px;
  }
  .home-cover-card{
    width:100%;
    border-radius:22px;
    padding:24px;
    background:#f9f6ef;
  }
  .home-cover h1{
    font-size:clamp(2.6rem,9vw,4.5rem);
  }
  .home-worship-strip-inner{
    grid-template-columns:1fr;
    gap:18px;
  }
  .home-worship-copy{
    padding-left:0;
    border-left:0;
  }
  .home-bulletin-link{
    width:max-content;
  }
}
@media(max-width:560px){
  .home-cover-actions{
    grid-template-columns:1fr;
  }
  .home-cover .home-cover-actions .action{
    min-height:72px;
  }
  .home-worship-times strong{
    white-space:normal;
  }
}
/* KCMC_HOME_OPTION_B_20261013 END */
